DROP VIEW IF EXISTS learninsurancedb.vw_users CASCADE;
CREATE VIEW learninsurancedb.vw_users AS
SELECT t.id, t.username, t.email, t.full_name, t.mobile, t.last_login_date, t.must_change_password, t.failed_login_count, t.locked_until,
       t.created_date, t.created_by, t.modified_date, t.modified_by, t.is_active,
       COALESCE((SELECT string_agg(r.name, ', ' ORDER BY r.name) FROM learninsurancedb.user_roles ur
                 JOIN learninsurancedb.roles r ON r.id = ur.role_id WHERE ur.user_id = t.id AND ur.is_active), '') AS role_names,
       COALESCE((SELECT jsonb_agg(ur.role_id ORDER BY ur.role_id) FROM learninsurancedb.user_roles ur
                 WHERE ur.user_id = t.id AND ur.is_active), '[]'::jsonb) AS role_ids
FROM learninsurancedb.users t;

-- LIST: search + filters + sort + paging. Returns { items, totalCount, page, pageSize }
DROP FUNCTION IF EXISTS learninsurancedb.fn_user_get_all(text, int, int, text, text, jsonb);
CREATE FUNCTION learninsurancedb.fn_user_get_all(
    p_search    text  DEFAULT NULL,
    p_page      int   DEFAULT 1,
    p_page_size int   DEFAULT 10,
    p_sort_by   text  DEFAULT NULL,
    p_sort_dir  text  DEFAULT NULL,
    p_filters   jsonb DEFAULT '{}'::jsonb
) RETURNS jsonb
LANGUAGE plpgsql STABLE AS $fn$
DECLARE
    v_page   int := GREATEST(COALESCE(p_page, 1), 1);
    v_size   int := LEAST(GREATEST(COALESCE(p_page_size, 10), 1), 500);
    v_sort   text := learninsurancedb.fn_to_snake(p_sort_by);
    v_dir    text := CASE WHEN lower(COALESCE(p_sort_dir, 'ASC')) = 'asc' THEN 'ASC' ELSE 'DESC' END;
    v_where  text := 'WHERE TRUE';
    v_like   text;
    v_key    text;
    v_val    text;
    v_col    text;
    v_total  bigint;
    v_items  jsonb;
BEGIN
    IF v_sort IS NULL OR NOT (v_sort = ANY (ARRAY['id', 'created_date', 'modified_date', 'is_active', 'username', 'email', 'full_name', 'last_login_date', 'role_names'])) THEN
        v_sort := 'full_name';
        IF p_sort_by IS NULL THEN v_dir := 'ASC'; END IF;
    END IF;

    IF p_search IS NOT NULL AND btrim(p_search) <> '' THEN
        v_like := '%' || btrim(p_search) || '%';
        v_where := v_where || format(' AND (username::text ILIKE %1$L OR email::text ILIKE %1$L OR full_name::text ILIKE %1$L OR mobile::text ILIKE %1$L OR role_names::text ILIKE %1$L)', v_like);
    END IF;

    FOR v_key, v_val IN SELECT key, value FROM jsonb_each_text(COALESCE(p_filters, '{}'::jsonb)) LOOP
        v_col := learninsurancedb.fn_to_snake(v_key);
        IF v_col = ANY (ARRAY['is_active']) AND COALESCE(v_val, '') <> '' THEN
            v_where := v_where || format(' AND %I::text = %L', v_col, v_val);
        END IF;
    END LOOP;

    EXECUTE format('SELECT count(*) FROM learninsurancedb.vw_users %s', v_where) INTO v_total;
    EXECUTE format(
        'SELECT COALESCE(jsonb_agg(learninsurancedb.fn_to_camel(to_jsonb(q))), ''[]''::jsonb)
         FROM (SELECT * FROM learninsurancedb.vw_users %s ORDER BY %I %s, id DESC LIMIT %s OFFSET %s) q',
        v_where, v_sort, v_dir, v_size, (v_page - 1) * v_size) INTO v_items;

    RETURN jsonb_build_object('items', v_items, 'totalCount', v_total, 'page', v_page, 'pageSize', v_size);
END
$fn$;

-- GET BY ID: returns the row as JSON, or NULL when not found
CREATE OR REPLACE FUNCTION learninsurancedb.fn_user_get_by_id(p_id bigint) RETURNS jsonb
LANGUAGE sql STABLE AS $fn$
    SELECT learninsurancedb.fn_to_camel(to_jsonb(v)) FROM learninsurancedb.vw_users v WHERE v.id = p_id;
