-- SET ACTIVE: soft delete / restore
CREATE OR REPLACE FUNCTION learninsurancedb.fn_user_set_active(p_id bigint, p_active boolean, p_user text DEFAULT 'system') RETURNS jsonb
LANGUAGE plpgsql AS $fn$
BEGIN
    UPDATE learninsurancedb.users SET is_active = p_active, modified_date = now(), modified_by = COALESCE(p_user, 'system')
    WHERE id = p_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'User % not found', p_id USING ERRCODE = 'P0002';
    END IF;
    RETURN learninsurancedb.fn_user_get_by_id(p_id);
END
$fn$;

-- DELETE (soft): sets is_active = false
CREATE OR REPLACE FUNCTION learninsurancedb.fn_user_delete(p_id bigint, p_user text DEFAULT 'system') RETURNS jsonb
LANGUAGE plpgsql AS $fn$
BEGIN
    PERFORM learninsurancedb.fn_user_set_active(p_id, FALSE, p_user);
    RETURN jsonb_build_object('id', p_id, 'deleted', TRUE);
END
$fn$;
